const e="gunnedah-eisteddfod-speech-drama",u=2022,n="Read the whole 2022 syllabus. It prints no points, grades or judging criteria and no prize amounts. It prints a PO Box and an enquiry email, which are the organiser's own. The syllabus is a past edition (2022): dates, fees and set pieces are kept as variables or noted by year. Set piece texts (Bible readings and the five choral speech poems) are named but not copied.",t={Title:"Rules and General Conditions of Entry",Subtitle:"Gunnedah Eisteddfod Speech, Drama and Public Speaking: rules, entry and set pieces",NoticeTitle:"Please Read Before Registering",Notice:"Entries are online only and close on {{EntriesClose}}. Late or phone entries are not accepted. Read the description under each section for time limits, numbers and definitions.",Notes:["Entry closing date: {{EntriesClose}}. Online entries open {{EntriesOpen}}.","Programs are published on the eisteddfod website. Check the website for updates."],Sections:[{Key:"general",Title:"General rules",Items:["All sections are 'Own Choice' unless otherwise indicated (Preschool and Infants, Years 3 and 4, Years 5 and 6, High School notes).","Unless otherwise stated, only one item may be performed in each section by an entrant (rule 8).","No entrant may perform the same item in more than one section (rule 11).","No contestant may say a poem as 'Own Choice' if it is a set piece in the current eisteddfod (rule 10).","Copies of own choice pieces must be received by the start of the session in which they are performed. Copies of plays are emailed to the convenors as the syllabus says (rule 2).","No deferment of adjudication to a later session is permitted. Deferment within a session is at the adjudicator's discretion (rule 12).","The committee may change the program at any time by changing the order of entrants or sections at any session (rule 13).","The committee may appoint a substitute adjudicator (rule 14).","Competitors must meet the requirements of their section (time limits, minimum and maximum numbers, definitions). Failure to do so may result in disqualification (rule 20).","All entrants perform entirely at their own risk (rule 3).","Cancellation: if the eisteddfod is cancelled, entry fees are reimbursed less the booking fee and credit card fees (rule 1).","Covid-19: the committee may put Covid-19 rules in place (rule 19)."]},{Key:"eligibility",Title:"Who may enter",Items:["The entrant's age is their age on the first day of May each year (rule 4).","Entrants in sections limited by age must be ready to show proof of age if asked (rule 4).","Open sections in speech and drama are open to entrants aged 16 and over (rule 5).","Classes are by school year: Preschool, Kindergarten, Years 1 to 12, and combined classes such as Years 3 and 4 (syllabus section headings).","An entrant must not repeat any item with which they won first place in a previous Gunnedah Eisteddfod, unless it is a set piece (rule 9).","Choral speech Years 5 and 6, 3 and 4, 1 and 2 and Kindergarten are for school groups of those years. Choral speech for a school with fewer than 65 pupils has its own section.","High School Speak Off: two representatives in each Year level from Years 7, 8, 9, 10, 11 and 12 (section HS 26)."]},{Key:"registration",Title:"How to enter",Items:["Entries must be completed online on the eisteddfod website. This is the only way to enter (rule 1).","Online entries open {{EntriesOpen}} and close {{EntriesClose}}. Late or phone entries are not accepted.","For help with the online entry, email {{OrganiserContact}} with the subject 'Eisteddfod Entries'. Include a contact number and a description of the issue.","Drama entries: after entering, the teacher emails the convenors with the subject 'Attn Speech & Drama One Act Play'. Include the performance length and a copy of the script with a cast list and the name of the actor playing each part.","The committee may cancel a section with too few entries. Entrants receive notice of cancellation (rule 6).","If a drama section has too few entries, the convenors may combine it with another section or drop it and will tell the entrants affected."]},{Key:"fees",Title:"Entry fees",Items:["Entry fees: {{EntryFees}}.","A booking fee and credit card fees are not returned if the eisteddfod is cancelled (rule 1)."]},{Key:"dates",Title:"Dates",Items:["Speech, Drama and Public Speaking Eisteddfod: {{EventDates}}.","Syllabus published: {{SyllabusPublished}}."]},{Key:"venue",Title:"Venues",Items:["Sessions are held at {{Venue}}."]},{Key:"judging",Title:"Judging and results",Items:["The adjudicator's decision is final (rule 15).","Where fewer than three entries are received in a section, the award of first or any prize is left to the adjudicator's discretion (rule 7).","Award sheets are ready 15 minutes after the adjudication ends and are the responsibility of the entrant (rule 17)."]},{Key:"complaints",Title:"Protests",Items:["A protest must be lodged in writing with the relevant convenor within 30 minutes of the cause of complaint. It must come with a deposit of {{ProtestDeposit}}, which is refunded if the protest is upheld (rule 16)."]},{Key:"conduct",Title:"Conduct and staging",Items:["Convenors may ban video cameras because filming breaches copyright law (rule 18).","Choral speech: teachers must not sing, speak or play with the choir or group they conduct. Failure to follow this rule may lead to disqualification.","No teacher, except as conductor, may be on stage at any time while their pupils are performing."]},{Key:"teams",Title:"Groups, pairs and choirs",Items:["Poems for Two are performed by two entrants and have their own entry fee.","Duologues are a scene for two actors.","Choral speech choirs present two pieces: a set piece and a contrasting own choice poem.","Drama: plays should be suitable for the year and stage level of the students."]},{Key:"prizes",Title:"Awards",Items:["High School Speak Off: individuals are marked, all results are added up and the school with the highest overall mark is the Speak Off Champion School."]},{Key:"other",Title:"Who to contact and other notes",Items:["Convenors for 2022: {{Convenors}}. General enquiries go to {{Secretary}}."]}],Documents:[{Title:"Speech, Drama and Public Speaking Syllabus 2022 (PDF)",Url:"https://gunnedaheisteddfod.com.au/wp-content/uploads/2022/03/PUB_GDHEist_SpeechDramaSyllabus2022_2402_FINAL.pdf"}]},a=[],o=[],s=JSON.parse(`[{"Title":"Nursery Rhyme in Costume","Source":"Syllabus 2022, Preschool and Infants (PF 1, PF 2)","Sections":{"About":null,"TimeAndFormat":null,"Rules":["For Preschool and Kindergarten entrants, in costume."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Rules\\n- For Preschool and Kindergarten entrants, in costume."},{"Title":"Poem for One","Source":"Syllabus 2022, all sections (PF 3, PF 4, JP 2, JP 3, SP 2, SP 3, JH 3, MH 12, SH 20)","Sections":{"About":null,"TimeAndFormat":["Infants and Years 3 and 4: 2 minutes. Years 5 and 6: 3 minutes."],"Rules":["Own choice."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Infants and Years 3 and 4: 2 minutes. Years 5 and 6: 3 minutes.\\n\\n## Rules\\n- Own choice."},{"Title":"Australian Poem","Source":"Syllabus 2022, all sections (PF 5, JP 1, SP 1, JH 4, MH 13, SH 21)","Sections":{"About":null,"TimeAndFormat":["Infants and Years 3 and 4: 2 minutes. Years 5 and 6: 3 minutes."],"Rules":["Own choice."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Infants and Years 3 and 4: 2 minutes. Years 5 and 6: 3 minutes.\\n\\n## Rules\\n- Own choice."},{"Title":"Original Poem","Source":"Syllabus 2022, JP 15, SP 13","Sections":{"About":null,"TimeAndFormat":["The poem time limit of the age level: 2 minutes for Years 3 and 4 and 3 minutes for Years 5 and 6."],"Rules":["The entrant presents a poem they wrote themselves."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- The poem time limit of the age level: 2 minutes for Years 3 and 4 and 3 minutes for Years 5 and 6.\\n\\n## Rules\\n- The entrant presents a poem they wrote themselves."},{"Title":"Poem for Two","Source":"Syllabus 2022, PF 6, JP 4, SP 11","Sections":{"About":null,"TimeAndFormat":["Infants and Years 3 and 4: 3 minutes. Years 5 and 6: 4 minutes."],"Rules":["Two performers. Infants: costume optional. Years 3 and 4, and Years 5 and 6: in costume.","The entry fee is {{PoemForTwoFee}} for the pair."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Infants and Years 3 and 4: 3 minutes. Years 5 and 6: 4 minutes.\\n\\n## Rules\\n- Two performers. Infants: costume optional. Years 3 and 4, and Years 5 and 6: in costume.\\n- The entry fee is {{PoemForTwoFee}} for the pair."},{"Title":"Duologue","Source":"Syllabus 2022, JP 12, SP 12, JH 6, MH 15, SH 23","Sections":{"About":null,"TimeAndFormat":["Years 3 and 4: 3 minutes. Years 5 and 6: 4 minutes."],"Rules":["A scene for two actors. Years 5 and 6 and High School: memorised.","Costume is optional."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Years 3 and 4: 3 minutes. Years 5 and 6: 4 minutes.\\n\\n## Rules\\n- A scene for two actors. Years 5 and 6 and High School: memorised.\\n- Costume is optional."},{"Title":"Mime","Source":"Syllabus 2022, PF 12, JP 5, SP 4, JH 5, MH 14, SH 22","Sections":{"About":null,"TimeAndFormat":["Kindergarten to Year 2: 2 minutes."],"Rules":null,"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Kindergarten to Year 2: 2 minutes."},{"Title":"Monologue","Source":"Syllabus 2022, PF 13, JP 6, SP 5, JH 1, JH 2, MH 9, MH 10, SH 17, SH 18","Sections":{"About":null,"TimeAndFormat":["Year 2: 1 minute."],"Rules":["Year 2: role play a character from a text. Years 5 and 6: a scripted role play for one actor, memorised."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Year 2: 1 minute.\\n\\n## Rules\\n- Year 2: role play a character from a text. Years 5 and 6: a scripted role play for one actor, memorised."},{"Title":"Shakespeare Monologue","Source":"Syllabus 2022, JH 7, MH 16, SH 24","Sections":{"About":null,"TimeAndFormat":null,"Rules":["High School Years 7 to 12 only."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Rules\\n- High School Years 7 to 12 only."},{"Title":"Bible Reading","Source":"Syllabus 2022, JP 7, SP 7 and Set Pieces","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Set piece. Years 3 and 4: Ephesians chapter 6, verses 1 and 2. Years 5 and 6: Matthew chapter 7, verses 24 to 27. The text is printed at the end of the syllabus."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Rules\\n- Set piece. Years 3 and 4: Ephesians chapter 6, verses 1 and 2. Years 5 and 6: Matthew chapter 7, verses 24 to 27. The text is printed at the end of the syllabus."},{"Title":"Prose Reading","Source":"Syllabus 2022, PF 7, JP 8, SP 6","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Years 1 and 2: prepared reading. Years 3 and 4: individual, and no costume is needed."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Rules\\n- Years 1 and 2: prepared reading. Years 3 and 4: individual, and no costume is needed."},{"Title":"Impromptu Reading","Source":"Syllabus 2022, JP 9, JP 10, SP 8, SP 9","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Each year level has its own section."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Rules\\n- Each year level has its own section."},{"Title":"Indigenous Story Telling","Source":"Syllabus 2022, JP 11, SP 10","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Years 3 and 4, and Years 5 and 6."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Rules\\n- Years 3 and 4, and Years 5 and 6."},{"Title":"Introduce a Book","Source":"Syllabus 2022, PF 9, PF 10, PF 11, JP 14","Sections":{"About":null,"TimeAndFormat":["1 minute."],"Rules":["Talk about the name of the book, the setting, favourite characters and points of interest (helpful hints in the syllabus)."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- 1 minute.\\n\\n## Rules\\n- Talk about the name of the book, the setting, favourite characters and points of interest (helpful hints in the syllabus)."},{"Title":"Describe a Picture","Source":"Syllabus 2022, PF 8","Sections":{"About":null,"TimeAndFormat":["1 minute."],"Rules":["Kindergarten to Year 2. The child chooses their own picture (from a book, a photo or a magazine) and displays it.","Helpful hints: talk about why they chose the picture, what it means to them and how it makes them feel, not only what is in it."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- 1 minute.\\n\\n## Rules\\n- Kindergarten to Year 2. The child chooses their own picture (from a book, a photo or a magazine) and displays it.\\n- Helpful hints: talk about why they chose the picture, what it means to them and how it makes them feel, not only what is in it."},{"Title":"Prepared Speech","Source":"Syllabus 2022, Prepared and Impromptu Public Speaking (PS 1, PS 3, PS 5, PS 7)","Sections":{"About":null,"TimeAndFormat":["Years 3 and 4: 2 minutes. Years 5 and 6: 3 minutes."],"Rules":null,"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Years 3 and 4: 2 minutes. Years 5 and 6: 3 minutes."},{"Title":"Impromptu Speech","Source":"Syllabus 2022, Prepared and Impromptu Public Speaking (PS 2, PS 4, PS 6, PS 8)","Sections":{"About":null,"TimeAndFormat":["1 minute."],"Rules":null,"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- 1 minute."},{"Title":"Theatre Sports","Source":"Syllabus 2022, Special Eisteddfod Event (HS 25)","Sections":{"About":null,"TimeAndFormat":["5 minutes."],"Rules":["New section. The entry fee is {{TheatreSportsFee}}."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- 5 minutes.\\n\\n## Rules\\n- New section. The entry fee is {{TheatreSportsFee}}."},{"Title":"High School Speak Off","Source":"Syllabus 2022, Special Eisteddfod Event (HS 26)","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Years 7, 8, 9, 10, 11 and 12, with two representatives in each Year level.","The entry fee is {{SpeakOffFee}}."],"Allowed":null,"NotAllowed":null,"Judging":["Individuals are marked and all results are compiled. The school with the highest overall mark is the Speak Off Champion School."],"Points":null,"Notes":null},"Markdown":"## Rules\\n- Years 7, 8, 9, 10, 11 and 12, with two representatives in each Year level.\\n- The entry fee is {{SpeakOffFee}}.\\n\\n## Judging\\n- Individuals are marked and all results are compiled. The school with the highest overall mark is the Speak Off Champion School."},{"Title":"One Act Play","Source":"Syllabus 2022, School Sections, Drama (DR 1)","Sections":{"About":null,"TimeAndFormat":["30 minutes, including setting and striking the stage."],"Rules":["Primary schools. The entry fee is {{GroupFee}}."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":["After entering, the teacher emails the script with a cast list to the convenors."]},"Markdown":"## Time and format\\n- 30 minutes, including setting and striking the stage.\\n\\n## Rules\\n- Primary schools. The entry fee is {{GroupFee}}.\\n\\n## Notes for participants\\n- After entering, the teacher emails the script with a cast list to the convenors."},{"Title":"Group Mime","Source":"Syllabus 2022, School Sections, Drama (DR 2)","Sections":{"About":null,"TimeAndFormat":["30 minutes, including setting and striking the stage."],"Rules":["Primary schools. The entry fee is {{GroupFee}}."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- 30 minutes, including setting and striking the stage.\\n\\n## Rules\\n- Primary schools. The entry fee is {{GroupFee}}."},{"Title":"Choral Speech","Source":"Syllabus 2022, School Sections, Choral Speech (CS 1 to CS 5)","Sections":{"About":null,"TimeAndFormat":["2 minutes. Kindergarten set piece: 1 minute."],"Rules":["Choirs present two pieces: (a) the set piece and (b) a contrasting own choice poem.","Set pieces: Years 5 and 6 'Mrs McGill' by Jeremy Green; Years 3 and 4 'Giggles & Woes' by Annette Kosseris; Years 1 and 2 'Concert Night' by Katherine Blowen; Kindergarten 'On With the Show' by Annette Kosseris; schools with fewer than 65 pupils 'What a Performance' by Jeremy Green.","The entry fee is {{GroupFee}}."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- 2 minutes. Kindergarten set piece: 1 minute.\\n\\n## Rules\\n- Choirs present two pieces: (a) the set piece and (b) a contrasting own choice poem.\\n- Set pieces: Years 5 and 6 'Mrs McGill' by Jeremy Green; Years 3 and 4 'Giggles & Woes' by Annette Kosseris; Years 1 and 2 'Concert Night' by Katherine Blowen; Kindergarten 'On With the Show' by Annette Kosseris; schools with fewer than 65 pupils 'What a Performance' by Jeremy Green.\\n- The entry fee is {{GroupFee}}."}]`),l=[],i=[{Key:"EntriesOpen",Kind:"date",Label:"Online entries open",Value:"2022-02-28",Source:"Syllabus 2022, back page"},{Key:"EntriesClose",Kind:"date",Label:"Entries close",Value:"2022-04-08",Source:"Syllabus 2022, cover and back page"},{Key:"SyllabusPublished",Kind:"date",Label:"Syllabus published",Value:"2022-02-24",Source:"Syllabus 2022, page headers"},{Key:"EventDates",Kind:"text",Label:"Eisteddfod dates",Value:"30 May to 2 June 2022",Source:"Syllabus 2022, cover"},{Key:"Venue",Kind:"address",Label:"Venues",Value:{Name:"Town Hall Gunnedah and Civic Theatre Gunnedah",Address:"",City:"Gunnedah, NSW",MapUrl:"",Directions:""},Source:"Syllabus 2022, cover"},{Key:"EntryFees",Kind:"fee",Label:"Entry fees",Value:"Individual entries $5; Poems for Two $10; Groups (choral speech and plays) $20",Source:"Syllabus 2022, cover"},{Key:"PoemForTwoFee",Kind:"fee",Label:"Poems for Two entry fee",Value:"$10",Source:"Syllabus 2022, cover"},{Key:"TheatreSportsFee",Kind:"fee",Label:"Theatre Sports entry fee",Value:"$10",Source:"Syllabus 2022, HS 25"},{Key:"SpeakOffFee",Kind:"fee",Label:"High School Speak Off entry fee",Value:"$50",Source:"Syllabus 2022, HS 26"},{Key:"GroupFee",Kind:"fee",Label:"Group entry fee (plays and choral speech)",Value:"$20",Source:"Syllabus 2022, cover and School Sections"},{Key:"ProtestDeposit",Kind:"fee",Label:"Protest deposit",Value:"$10",Source:"Syllabus 2022, rule 16"},{Key:"OrganiserContact",Kind:"contact",Label:"Contact for entry help and drama scripts",Value:{Name:"Gunnedah Eisteddfod",Role:"Entries help and one act play scripts",Phone:"",WhatsApp:"",Email:"gunnedahesiteddfod@gmail.com"},Source:"Syllabus 2022, School Sections and back page"},{Key:"Secretary",Kind:"contact",Label:"Secretary for general enquiries",Value:{Name:"The Secretary, Gunnedah Eisteddfod Society (Inc)",Role:"General enquiries, by post to PO Box 372, Gunnedah NSW 2380",Phone:"",WhatsApp:"",Email:""},Source:"Syllabus 2022, rule 21"},{Key:"Convenors",Kind:"text",Label:"Convenors",Value:"Mrs Kate Pinn and Mrs Rebecca Dowe",Source:"Syllabus 2022, cover"},{Key:"Announcements",Kind:"news",Label:"Notices printed in the syllabus",Value:[{Date:"2022-02-28",Title:"Online entries open",Text:"Online entries open on Monday 28 February 2022. Check the website for updates; programs are published on the Gunnedah Eisteddfod website.",Url:""},{Date:"",Title:"New section: Theatre Sports",Text:"Theatre Sports (HS 25) is a new section for 2022. Entry fee $10, time limit 5 minutes.",Url:""},{Date:"",Title:"70th Gunnedah Eisteddfod",Text:"The syllabus welcomes entrants to the 70th Gunnedah Eisteddfod.",Url:""}],Source:"Syllabus 2022, pages 1, 7 and 15"}],r=[{Claim:"Rules, fees, dates, venues, set pieces and section conditions are from the organiser's own 2022 speech and drama syllabus.",SourceType:"Primary - the event's own rules document",Source:"Gunnedah Eisteddfod 2022 Speech, Drama and Public Speaking Syllabus",Url:"https://gunnedaheisteddfod.com.au/wp-content/uploads/2022/03/PUB_GDHEist_SpeechDramaSyllabus2022_2402_FINAL.pdf"}],d={TemplateKey:e,Year:2022,Note:n,Page:t,ParticipantTypes:a,AgeGroups:o,Competitions:s,CompetitionAgeGroups:l,Variables:i,Evidence:r};export{o as AgeGroups,l as CompetitionAgeGroups,s as Competitions,r as Evidence,n as Note,t as Page,a as ParticipantTypes,e as TemplateKey,i as Variables,u as Year,d as default};
